```ts
    clearWatched(): number {
        let removed = 0;
        this._items.update(items => {
            const remaining = items.filter(m => {
                if (m.watched) {
                    removed++;
                    return false;
                }
                return true;
            });
            return removed === 0 ? items : remaining;
        });
        return removed;
